Constants
import {
  DEFAULT_WINDOW_DIMENSIONS, // { defaultWidth: 800, defaultHeight: 600, ... }
  TASKBAR_HEIGHT,            // 48
  ICON_COLUMN_WIDTH,         // 80
  BREAKPOINTS,               // { mobile: 480, tablet: 768, desktop: 1024 }
  ANIMATION_DURATION,        // 0.3 (seconds)
  AVAILABLE_FONTS,           // string[]
  APP_IDS,                   // Record&lt;string, string&gt;
  DEFAULT_LAUNCHER_FOLDERS,  // predefined folder definitions
  // animation helpers:
  createWindowVariants, windowVariants, panelVariants,
  randomWindowPosition, centerWindowPosition,
} from &#039;@fde-desktop/fde-core&#039;;

i18n
import { i18n } from &#039;@fde-desktop/fde-core&#039;;
Pre-configured i18next instance with en / es support and namespaces: common, apps, settings, window, contextMenu, notifications, welcome, notes.
