// Renders: &quot;Alice, Bob are typing...&quot; with animated dots
AttachmentPreview
File/image preview:
&lt;AttachmentPreview
  file={file}
  onRemove={handleRemove}
  thumbnail={thumbnailUrl}
/&gt;
Types
interface ChatMessage {
  id: string;
  sender: string;
  content: string;
  timestamp: Date;
  status: &#039;sending&#039; | &#039;sent&#039; | &#039;delivered&#039; | &#039;read&#039; | &#039;error&#039;;
  attachments?: Attachment[];
}

interface Attachment {
  id: string;
  name: string;
  type: &#039;image&#039; | &#039;file&#039; | &#039;video&#039; | &#039;audio&#039;;
  url: string;
  thumbnail?: string;
  size: number;
}

interface ChatUser {
  id: string;
  name: string;
  avatar?: string;
  isTyping?: boolean;
}
Usage Example
import { ChatWindow } from &#039;@fde-desktop/chat&#039;;
import { useState } from &#039;react&#039;;

function MyApp() {
  const [messages, setMessages] = useState&lt;ChatMessage[]&gt;([]);

  const handleSend = (content: string, attachments?: File[]) =&gt; {
    const message: ChatMessage = {
      id: crypto.randomUUID(),
      sender: &#039;me&#039;,
      content,
      timestamp: new Date(),
      status: &#039;sending&#039;,
    };
    setMessages(prev =&gt; [...prev, message]);
  };

  return (
    &lt;ChatWindow
      messages={messages}
      onSendMessage={handleSend}
      typingUsers={[&#039;Alice&#039;]}
    /&gt;
  );
}
