cd packages/chat
bun run storybook
Integration with FDE Desktop
To use chat in a custom app:
// src/Presentation/Components/Apps/ChatApp/ChatApp.tsx
import { ChatWindow } from &#039;@fde-desktop/chat&#039;;

export function ChatApp() {
  return (
    &lt;ChatWindow
      messages={messages}
      onSendMessage={handleSend}
      typingUsers={typingUsers}
    /&gt;
  );
}
